package run.ikaros.reading; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/reading") public class ReadingProgressController{private final ReadingProgressService service;public ReadingProgressController(ReadingProgressService s){service=s;}@PostMapping("/works/{workId}/sessions")public Mono<ReadingSessionView> start(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID workId,@Valid@RequestBody StartReadingSessionRequest r){return service.start(o,workId,r);}@PatchMapping("/sessions/{sessionId}")public Mono<ReadingSessionView> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID sessionId,@Valid@RequestBody UpdateReadingProgressRequest r){return service.update(o,sessionId,r);}@PostMapping("/sessions/{sessionId}/actions/end")public Mono<ReadingSessionView> end(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID sessionId){return service.end(o,sessionId);}@GetMapping("/works/{workId}/progress")public Mono<ReadingProgressView> progress(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID workId,@RequestParam UUID editionId){return service.progress(o,workId,editionId);}@GetMapping("/history")public Flux<ReadingHistoryView> history(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return service.history(o);}}
